def log(msg):
    print(f"[VantaLauncher] {msg}", flush=True)
    try:
        with open(LOG_PATH, "a", encoding="utf-8") as f:
            f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {msg}\n")
    except Exception:
        pass


def _fail(msg):
    raise ImportError(f"Vanta Vision 2K27: {msg}")


# Runtime selection never changes the ABI of the Python process hosting CVPython.
_DLL_HANDLES = []
_DLL_PATHS = set()
_RUNTIME_INFO = None
_RUNTIME_LOCK = threading.RLock()
_CA_PATH = None
_STATE_DIR = os.path.join(os.environ.get('LOCALAPPDATA') or tempfile.gettempdir(), 'VantaVision', 'Launcher')
os.makedirs(_STATE_DIR, exist_ok=True)
LOG_PATH = os.path.join(_STATE_DIR, 'VantaLauncher.log')


def _clean_child_env():
    env = os.environ.copy()
    for key in ('PYTHONHOME', 'PYTHONPATH', 'QT_PLUGIN_PATH', 'QT_QPA_PLATFORM_PLUGIN_PATH', 'QML2_IMPORT_PATH'):
        env.pop(key, None)
    if env.get('SSL_CERT_DIR') and not os.path.isdir(env['SSL_CERT_DIR']):env.pop('SSL_CERT_DIR',None)
    for key in ('SSL_CERT_FILE', 'REQUESTS_CA_BUNDLE', 'CURL_CA_BUNDLE'):
        if env.get(key) and not os.path.isfile(env[key]):
            env.pop(key, None)
    env['PYTHONNOUSERSITE'] = '1'
    env['PYTHONUTF8'] = '1'
    return env


_PROBE_CODE = r'''
import sys,json,struct,os
result={'version':list(sys.version_info[:2]),'bits':struct.calcsize('P')*8,'exe':sys.executable,'prefix':sys.prefix,'paths':[],'errors':{}}
import sysconfig
result['paths']=list(dict.fromkeys(p for p in (sysconfig.get_path('purelib'),sysconfig.get_path('platlib')) if p))
for name in ('ssl','PyQt6.QtCore','PyQt6.QtGui','PyQt6.QtWidgets','numpy','cv2','requests'):
    try:__import__(name)
    except Exception as exc:result['errors'][name]=str(exc)
try:
    import ssl
    result['openssl']=ssl.OPENSSL_VERSION
except Exception:pass
if sys.platform=='win32' and not any(k.startswith('PyQt6') for k in result['errors']):
    from PyQt6.QtCore import QLibraryInfo
    platform=os.path.join(QLibraryInfo.path(QLibraryInfo.LibraryPath.PluginsPath),'platforms','qwindows.dll')
    if not os.path.isfile(platform):result['errors']['PyQt6.platforms']='Missing qwindows.dll'
print('DRS_PROBE:'+json.dumps(result))
'''


def _probe_python(exe):
    if not exe or not os.path.isfile(exe) or 'windowsapps' in exe.lower() or not os.path.basename(exe).lower().startswith('python'):
        return None
    try:
        process = subprocess.run([exe, '-I', '-c', _PROBE_CODE], env=_clean_child_env(),
            capture_output=True, text=True, encoding='utf-8', errors='replace', timeout=35,
            creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        lines = [line[10:] for line in process.stdout.splitlines() if line.startswith('DRS_PROBE:')]
        if process.returncode != 0 or not lines:
            return None
        result = json.loads(lines[-1])
        if result['version'] != list(sys.version_info[:2]) or result['bits'] != 64:
            return None
        return result
    except Exception:
        return None


def _python_candidates():
    guesses = [os.environ.get('VANTA_PYTHON_EXE'), os.environ.get('VV_PYTHON_EXE'), _PY_ENV_EXE]
    for base in (_HERE, os.path.dirname(_HERE)):
        guesses.extend(os.path.join(base, folder, 'python.exe') for folder in ('py-env', 'VantaEnvironment/py-env', 'VantaEnvironment/py-env'))
    guesses.extend([sys.executable, os.path.join(sys.prefix, 'python.exe'), os.path.join(sys.base_prefix, 'python.exe')])
    version = f'{sys.version_info.major}{sys.version_info.minor}'
    guesses.extend([os.path.expandvars(r'%LOCALAPPDATA%\Programs\Python\Python'+version+r'\python.exe'),
                   os.path.expandvars(r'%USERPROFILE%\Miniconda3\python.exe'),
                   os.path.expandvars(r'%USERPROFILE%\miniconda3\python.exe')])
    for name in ('python.exe', 'python3.exe', 'python'):
        guesses.append(shutil.which(name))
    if os.name == 'nt':
        try:
            result = subprocess.run(['py', '-0p'], capture_output=True, text=True, timeout=8,
                env=_clean_child_env(), creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
            guesses.extend(re.findall(r'([A-Za-z]:\\[^\r\n]*?python(?:w)?\.exe)', result.stdout, re.I))
        except Exception:
            pass
    seen = set()
    for guess in guesses:
        if not guess:
            continue
        guess = os.path.abspath(os.path.expandvars(guess))
        key = os.path.normcase(guess)
        if key not in seen:
            seen.add(key)
            yield guess


def _select_runtime(refresh=False):
    global _RUNTIME_INFO
    with _RUNTIME_LOCK:
        if _RUNTIME_INFO is not None and not refresh:
            return _RUNTIME_INFO
        candidates = []
        for exe in _python_candidates():
            info = _probe_python(exe)
            if info is None or 'ssl' in info['errors']:
                continue
            loaded=sys.modules.get('PyQt6.QtCore')
            if loaded is not None:
                origin=os.path.realpath(getattr(loaded,'__file__',''))
                compatible=False
                for path in info['paths']:
                    try:compatible |= os.path.commonpath([os.path.realpath(path),origin])==os.path.realpath(path)
                    except ValueError:pass
                if not compatible:continue
            candidates.append(info)
            if not info['errors']:
                _RUNTIME_INFO = info
                return info
        if candidates:
            _RUNTIME_INFO = min(candidates, key=lambda item: len(item['errors']))
            return _RUNTIME_INFO
        raise RuntimeError(f'No working 64-bit Python {sys.version_info.major}.{sys.version_info.minor} runtime was found. '
            'Select that Python version in the CVPython host, or place a complete matching py-env beside this launcher. '
            'A different-version environment cannot load this compiled core.')


def _bundled_pyenv_is_complete():
    info = _probe_python(_PY_ENV_EXE)
    return bool(info and not info['errors'])


def _find_safe_python_exe():
    return _select_runtime()['exe']


def _keep_dll_directory(path):
    key=os.path.normcase(os.path.realpath(path))
    if key not in _DLL_PATHS and os.path.isdir(path) and hasattr(os, 'add_dll_directory'):
        _DLL_HANDLES.append(os.add_dll_directory(path));_DLL_PATHS.add(key)


def _wire_bundled_env():
    info = _select_runtime()
    if info['errors']:
        missing = ', '.join(info['errors'])
        raise RuntimeError(f'Runtime needs repair: {missing}. Click Repair Runtime. Python: {info["exe"]}')
    # Load only packages verified under this exact Python major/minor and architecture.
    paths = [path for path in info['paths'] if os.path.isdir(path)]
    loaded=sys.modules.get('PyQt6.QtCore')
    if loaded is not None:
        origin=os.path.realpath(getattr(loaded,'__file__',''))
        def contains(path):
            try:return os.path.commonpath([os.path.realpath(path),origin])==os.path.realpath(path)
            except ValueError:return False
        if not any(contains(path) for path in paths):
            raise RuntimeError('A different Qt runtime is already loaded in this host. Set the host Python to '+info['exe']+' and restart it.')

    for path in reversed(paths):
        if path not in sys.path:
            sys.path.insert(0, path)
        for folder in ('pywin32_system32', 'win32', os.path.join('PyQt6','Qt6','bin')):
            _keep_dll_directory(os.path.join(path, folder))
        for subpath in ('win32', os.path.join('win32','lib'), 'Pythonwin'):
            full = os.path.join(path, subpath)
            if os.path.isdir(full) and full not in sys.path:
                sys.path.append(full)
    prefix = info['prefix']
    for folder in ('', 'DLLs', os.path.join('Library','bin')):
        _keep_dll_directory(os.path.join(prefix, folder))
    os.environ['VV_PYTHON_EXE'] = info['exe']
    os.environ['VANTA_PYTHON_EXE'] = info['exe']
    # Do not inject PYTHONHOME or PYTHONPATH into the already-running host.
    for key in ('QT_PLUGIN_PATH','QT_QPA_PLATFORM_PLUGIN_PATH','QML2_IMPORT_PATH'):
        os.environ.pop(key, None)
    for module in ('ssl','PyQt6.QtCore','PyQt6.QtGui','PyQt6.QtWidgets','numpy','cv2','requests'):
        try:
            importlib.import_module(module)
        except Exception as exc:
            raise RuntimeError(f'{module} failed in the CVPython host: {exc}. '
                f'Set the host Python runtime to {info["exe"]} and restart the host.') from exc
    import PyQt6.QtCore as qtcore
    plugin_dir = qtcore.QLibraryInfo.path(qtcore.QLibraryInfo.LibraryPath.PluginsPath)
    if os.path.isdir(plugin_dir):
        qtcore.QCoreApplication.addLibraryPath(plugin_dir)
    return info


def _ssl_context():
    import ssl
    for key in ('SSL_CERT_FILE','REQUESTS_CA_BUNDLE','CURL_CA_BUNDLE'):
        path = os.environ.get(key)
        if path and not os.path.isfile(path):
            os.environ.pop(key, None)
    context = ssl.create_default_context()
    try:
        import certifi
        context.load_verify_locations(cafile=certifi.where())
    except ImportError:
        pass
    # Honor a valid custom company CA without discarding OS trust roots.
    for key in ('SSL_CERT_FILE','REQUESTS_CA_BUNDLE'):
        path = os.environ.get(key)
        if path and os.path.isfile(path):
            context.load_verify_locations(cafile=path)
    return context


def _configure_certificates():
    global _CA_PATH
    import ssl
    context = _ssl_context()
    pem = ''.join(ssl.DER_cert_to_PEM_cert(cert) for cert in context.get_ca_certs(binary_form=True))
    if not pem:
        raise RuntimeError('No trusted root certificates are available. Repair the Python installation or Windows root certificates.')
    path = os.path.join(_STATE_DIR, 'trusted-roots.pem')
    fd, temporary = tempfile.mkstemp(dir=_STATE_DIR, suffix='.pem')
    try:
        with os.fdopen(fd, 'w', encoding='ascii') as file:
            file.write(pem)
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):os.unlink(temporary)
    _CA_PATH = path
    os.environ['SSL_CERT_FILE'] = path
    os.environ['REQUESTS_CA_BUNDLE'] = path
    return path


def runtime_preflight(refresh=False):
    if refresh:
        _select_runtime(refresh=True)
    info = _wire_bundled_env()
    _configure_certificates()
    log('Runtime verified: '+info['exe'])
    return info


def repair_runtime(status_cb=log):
    info = _select_runtime()
    exe = info['exe']
    status_cb('Repairing dependencies in the selected Python runtime…')
    env = _clean_child_env()
    try:
        cert = _configure_certificates()
    except (ImportError, RuntimeError):
        cert = None
    flags = {'env':env, 'capture_output':True, 'text':True, 'encoding':'utf-8', 'errors':'replace',
             'timeout':480, 'creationflags':getattr(subprocess,'CREATE_NO_WINDOW',0)}
    pip = subprocess.run([exe,'-I','-m','pip','--version'], **flags)
    if pip.returncode:
        boot = subprocess.run([exe,'-I','-m','ensurepip','--upgrade'], **flags)
        if boot.returncode:
            raise RuntimeError('This runtime has no working pip/ensurepip. Install a complete matching Python runtime. '+boot.stderr[-800:])
    packages = ['PyQt6>=6.6,<7','numpy','opencv-python','requests','certifi']
    if os.name=='nt':packages.append('pywin32')
    command = [exe,'-I','-m','pip','--isolated','install','--disable-pip-version-check','--only-binary=:all:']
    if cert:command += ['--cert',cert]
    # Repair missing/broken dependencies, without mass-upgrading an already healthy stack.
    command += packages
    result = subprocess.run(command, **flags)
    log(result.stdout[-5000:])
    if result.returncode:
        raise RuntimeError('Dependency repair failed: '+result.stderr[-1400:])
    refreshed=_select_runtime(refresh=True)
    repair_packages=[]
    mapping={'numpy':['numpy'],'cv2':['opencv-python'],'requests':['requests'],
             'PyQt6.platforms':['PyQt6>=6.6,<7'],'PyQt6.QtCore':['PyQt6>=6.6,<7'],'PyQt6.QtGui':['PyQt6>=6.6,<7'],'PyQt6.QtWidgets':['PyQt6>=6.6,<7']}
    for module in refreshed['errors']:
        for package in mapping.get(module,[]):
            if package not in repair_packages:repair_packages.append(package)
    if repair_packages:
        reinstall=command[:command.index('install')+1]+['--disable-pip-version-check','--only-binary=:all:','--force-reinstall']
        if cert:reinstall+=['--cert',cert]
        result=subprocess.run(reinstall+repair_packages,**flags)
        if result.returncode:raise RuntimeError('Repair reinstall failed: '+result.stderr[-1400:])
        _select_runtime(refresh=True)
    return runtime_preflight()


def _legacy_expected_digest():
    ob = base64.b64decode(_E)
    kb = base64.b64decode(_K)
    return bytes(b ^ kb[i % len(kb)] for i, b in enumerate(ob))


def _sha256_file_hex(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 16), b""):
            h.update(chunk)
    return h.hexdigest()


def _hash_bytes_hex(data):
    return hashlib.sha256(data).hexdigest()


def _version_tuple(v):
    nums = re.findall(r"\d+", str(v or "0"))
    return tuple(int(x) for x in nums[:6]) if nums else (0,)


def _is_newer_version(latest, current):
    return _version_tuple(latest) > _version_tuple(current)


def _download_bytes(url, progress_cb=None):
    parsed=urllib.parse.urlsplit(str(url))
    if parsed.scheme!='https' or not parsed.hostname or parsed.username or parsed.password:
        raise ValueError('Update downloads require an HTTPS URL without embedded credentials.')
    req=urllib.request.Request(str(url),headers={'User-Agent':f'VantaLauncher/{APP_VERSION}','Accept':'application/octet-stream, application/json, */*','Cache-Control':'no-cache'})
    last=None
    for attempt in range(3):
        try:
            context=_ssl_context()
            # Redirects are checked as well; never downgrade TLS to plain HTTP.
            opener=urllib.request.build_opener(urllib.request.HTTPSHandler(context=context),_HTTPSOnlyRedirect())
            with opener.open(req,timeout=UPDATE_TIMEOUT_SECS) as response:
                total=int(response.headers.get('Content-Length') or 0)
                chunks=[];received=0
                while True:
                    chunk=response.read(256*1024)
                    if not chunk:break
                    chunks.append(chunk);received+=len(chunk)
                    if progress_cb:progress_cb(received,total)
                if total and received!=total:raise RuntimeError('Download incomplete; retrying the file.')
                return b''.join(chunks)
        except Exception as exc:
            last=exc
            if isinstance(exc,urllib.error.HTTPError) and exc.code not in (408,429,500,502,503,504):break
            if 'CERTIFICATE_VERIFY_FAILED' in str(exc) or isinstance(exc,ImportError):break
            if attempt<2:time.sleep(.4*(attempt+1))
    # A host with broken/missing _ssl can still fetch updates using a verified,
    # ABI-compatible helper Python; it is never allowed to load the core silently.
    if isinstance(last,ImportError) or 'CERTIFICATE_VERIFY_FAILED' in str(last) or 'SSL' in str(last):
        try:
            data=_download_with_runtime(str(url))
            if progress_cb:progress_cb(len(data),len(data))
            return data
        except Exception as helper_error:
            raise RuntimeError('Secure download failed. Check Windows date/time, proxy certificates, and the matching Python SSL installation. '+str(helper_error)) from last
    raise RuntimeError('Download failed: '+str(last)) from last


class _HTTPSOnlyRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self,req,fp,code,msg,headers,newurl):
        if urllib.parse.urlsplit(newurl).scheme.lower()!='https':
            raise RuntimeError('Refused an update redirect to an unencrypted URL.')
        return super().redirect_request(req,fp,code,msg,headers,newurl)


_HELPER_DOWNLOAD_CODE = r'''
import sys,ssl,urllib.request,urllib.parse,os
url,destination=sys.argv[1:3]
if urllib.parse.urlsplit(url).scheme!='https':raise ValueError('HTTPS required')
ctx=ssl.create_default_context()
try:
 import certifi
 ctx.load_verify_locations(cafile=certifi.where())
except ImportError:pass
for key in ('SSL_CERT_FILE','REQUESTS_CA_BUNDLE'):
 path=os.environ.get(key)
 if path and os.path.isfile(path):ctx.load_verify_locations(cafile=path)
class SecureRedirect(urllib.request.HTTPRedirectHandler):
 def redirect_request(self,req,fp,code,msg,headers,newurl):
  if urllib.parse.urlsplit(newurl).scheme!='https':raise ValueError('HTTPS redirect required')
  return super().redirect_request(req,fp,code,msg,headers,newurl)
opener=urllib.request.build_opener(urllib.request.HTTPSHandler(context=ctx),SecureRedirect())
req=urllib.request.Request(url,headers={'User-Agent':'VantaLauncher/2'})
with opener.open(req,timeout=25) as response,open(destination,'wb') as out:
 while True:
  chunk=response.read(1048576)
  if not chunk:break
  out.write(chunk)
'''


def _download_with_runtime(url):
    info=_select_runtime()
    fd,path=tempfile.mkstemp(prefix='drs-download-',suffix='.bin');os.close(fd)
    try:
        result=subprocess.run([info['exe'],'-I','-c',_HELPER_DOWNLOAD_CODE,url,path],env=_clean_child_env(),
            capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=90,
            creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
        if result.returncode:raise RuntimeError(result.stderr[-900:])
        with open(path,'rb') as file:return file.read()
    finally:
        if os.path.exists(path):os.unlink(path)


def _safe_update_path(rel):
    # Windows drive paths, UNC paths and alternate data streams must never escape the install folder.
    rel=str(rel).strip().replace('\\','/')
    if not rel or ':' in rel or rel.startswith('/') or any(part in ('','..','.') for part in rel.split('/')):
        raise ValueError('Invalid update path: '+rel)
    target=os.path.realpath(os.path.join(_HERE,*rel.split('/')))
    root=os.path.realpath(_HERE)
    if os.path.commonpath([root,target])!=root:raise ValueError('Update path escapes the application folder.')
    return target


def _backup_file(path):
    try:
        if os.path.isfile(path):
            os.makedirs(BACKUP_DIR, exist_ok=True)
            stamp = time.strftime("%Y%m%d_%H%M%S")
            shutil.copy2(path, os.path.join(BACKUP_DIR, f"{os.path.basename(path)}.{stamp}.bak"))
    except Exception:
        pass


def _replace_file(path, data):
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        _backup_file(path)
        fd,temporary=tempfile.mkstemp(dir=os.path.dirname(path),prefix='.drs-update-')
        try:
            with os.fdopen(fd,'wb') as file:file.write(data)
            os.replace(temporary,path)
        finally:
            if os.path.exists(temporary):os.unlink(temporary)
        return True
    except Exception as exc:
        log(f'Replace deferred for {os.path.basename(path)}: {exc}')
        try:
            relative=os.path.relpath(path,_HERE)
            _safe_update_path(relative)
            pending=os.path.join(PENDING_DIR,relative)
            os.makedirs(os.path.dirname(pending),exist_ok=True)
            with open(pending,'wb') as file:file.write(data)
        except Exception as pending_error:
            log('Could not stage update: '+str(pending_error))
        return False


def _apply_pending_updates():
    if not os.path.isdir(PENDING_DIR):return []
    applied=[]
    for directory,subdirs,names in os.walk(PENDING_DIR,followlinks=False):
        for name in names:
            source=os.path.join(directory,name)
            relative=os.path.relpath(source,PENDING_DIR)
            try:
                if os.path.islink(source):raise ValueError('Symlink in pending update')
                destination=_safe_update_path(relative)
                _backup_file(destination);os.makedirs(os.path.dirname(destination),exist_ok=True)
                os.replace(source,destination);applied.append(relative)
            except Exception as exc:log(f'Pending update still unavailable: {relative}: {exc}')
    return applied


def _runtime_sha_from_manifest(manifest):
    for item in manifest.get('files') or []:
        name=str(item.get('path') or item.get('name') or '').replace('\\','/').rsplit('/',1)[-1]
        if name.lower()==_CORE_BASENAME.lower():
            value=str(item.get('sha256') or '').strip().lower()
            if re.fullmatch(r'[0-9a-f]{64}',value):return value
    for key in ('runtime_sha256','pyd_sha256'):
        value=str(manifest.get(key) or '').strip().lower()
        if re.fullmatch(r'[0-9a-f]{64}',value):return value
    return ''


def _load_cached_manifest():
    try:
        if os.path.isfile(LOCAL_MANIFEST_CACHE):
            return json.loads(open(LOCAL_MANIFEST_CACHE, "r", encoding="utf-8").read())
    except Exception:
        pass
    return None


def _cache_manifest(manifest):
    try:
        with open(LOCAL_MANIFEST_CACHE, "w", encoding="utf-8") as f:
            json.dump(manifest, f, indent=2)
    except Exception:
        pass


def check_manifest():
    _apply_pending_updates()
    raw = _download_bytes(UPDATE_MANIFEST_URL)
    manifest = json.loads(raw.decode("utf-8", errors="replace"))
    if verify_runtime(manifest)[0]:_cache_manifest(manifest)
    return manifest


def _minimum_version(manifest):
    return str(manifest.get('min_required_version') or manifest.get('min_version_required') or '0')


def _mandatory_update_required(manifest):
    if not manifest:return False
    # A matching verified core is already the exact published update. A static
    # force_update flag must not trap this installation in an endless update loop.
    ok,_=verify_runtime(manifest)
    if ok:return False
    return bool(manifest.get('force_update') or _is_newer_version(_minimum_version(manifest),APP_VERSION))


def update_needed(manifest):
    ok,_=verify_runtime(manifest)
    if ok:return False
    latest=str(manifest.get('latest_version') or manifest.get('version') or '').strip()
    return bool(manifest.get('force_update') or _is_newer_version(latest,APP_VERSION)
                or _is_newer_version(_minimum_version(manifest),APP_VERSION))


def install_update(manifest, status_cb=None, progress_cb=None):
    normalized=[];seen=set()
    for item in manifest.get('files') or []:
        rel=str(item.get('path') or item.get('name') or '').strip().replace('\\','/')
        url=str(item.get('url') or item.get('download_url') or '').strip()
        expected=str(item.get('sha256') or '').strip().lower()
        target=_safe_update_path(rel)
        if target.lower() in seen:raise RuntimeError('Duplicate update path: '+rel)
        seen.add(target.lower())
        if not url or not re.fullmatch(r'[0-9a-f]{64}',expected):
            raise RuntimeError('Update manifest must include a download URL and SHA256 for '+rel)
        normalized.append((rel,url,expected))
    if not normalized:raise RuntimeError('The published update has no files to install.')
    installed=[];count=len(normalized)
    # Stage and verify the complete release before touching installed files.
    with tempfile.TemporaryDirectory(prefix='vanta-update-') as stage:
        staged=[]
        for index,(rel,url,expected) in enumerate(normalized):
            if status_cb:status_cb(f'Downloading {index+1}/{count}: {rel}')
            def report(received,total):
                fraction=min(received/total,1) if total else 0
                if progress_cb:progress_cb(85*(index+fraction)/count,
                    f'{index+1}/{count} files • {received/1048576:.1f} MB'+
                    (f' / {total/1048576:.1f} MB' if total else ' • downloading'))
            data=_download_bytes(url,report) if progress_cb else _download_bytes(url)
            actual=_hash_bytes_hex(data).lower()
            if actual!=expected:
                log(f'Update integrity mismatch: {rel}; expected={expected}; downloaded={actual}; bytes={len(data)}')
                raise RuntimeError(f'{rel} does not match the published hash. No update files were installed. '
                    'The publisher must upload matching files and SHA256 values. See Logs for details.')
            path=os.path.join(stage,str(index))
            with open(path,'wb') as output:output.write(data)
            staged.append((rel,path))
            if progress_cb:progress_cb(85*(index+1)/count,f'Verified {index+1}/{count} files')
        for index,(rel,path) in enumerate(staged):
            if status_cb:status_cb(f'Installing {index+1}/{count}: {rel}')
            with open(path,'rb') as source:data=source.read()
            if not _replace_file(_safe_update_path(rel),data):
                raise RuntimeError(f'{rel} is locked. Update saved pending. Close Gtuner and reopen.')
            installed.append(rel);log('installed '+rel)
            if progress_cb:progress_cb(85+15*(index+1)/count,f'Installed {index+1}/{count} files')
    _cache_manifest(manifest)
    return installed


def verify_runtime(manifest=None):
    _apply_pending_updates()
    if not os.path.isfile(_CORE_PATH):
        return False, f"Missing {_CORE_BASENAME}. This host requires 64-bit Python {_VI.major}.{_VI.minor} core files."
    actual = _sha256_file_hex(_CORE_PATH).lower()
    manifest = manifest or _load_cached_manifest() or {}
    expected = _runtime_sha_from_manifest(manifest)
    if expected:
        return (actual == expected), ("Runtime OK" if actual == expected else "Runtime SHA mismatch")
    try:
        matched = bytes.fromhex(actual) == _legacy_expected_digest()
        return matched, ("Runtime OK" if matched else "Runtime SHA mismatch")
    except Exception:
        return False, "Runtime integrity unknown"


def load_runtime():
    runtime_preflight()
    ok, msg = verify_runtime()
    if not ok:
        _fail(msg)
    if _HERE not in sys.path:
        sys.path.insert(0, _HERE)
    spec = importlib.util.spec_from_file_location("_vv_core", _CORE_PATH)
    if spec is None or spec.loader is None:
        _fail("could not create runtime module spec")
    core = importlib.util.module_from_spec(spec)
    sys.modules["_vv_core"] = core
    spec.loader.exec_module(core)
    for k in dir(core):
        if not k.startswith("__"):
            globals()[k] = getattr(core, k)
    return core


_VANTA_LOGO_B64 = ''

class VButton(tk.Button if tk is not None else object):
    def __init__(self, master, **kw):
        super().__init__(master, relief='flat', bd=0, cursor='hand2', font=('Segoe UI',10,'bold'),
            padx=12, pady=11, bg=kw.pop('bg',BUTTON_BG), fg=kw.pop('fg',TEXT),
            activebackground=kw.pop('activebackground',BUTTON_HOVER), activeforeground=TEXT,
            disabledforeground='#705C87', highlightthickness=1, highlightbackground=BORDER, **kw)


class UpdaterUI:
    def __init__(self, root):
        self.root=root;self.manifest=None;self.launch=False;self._closed=False;self._busy=False
        self._events=queue.Queue();self._runtime_ready=False
        root.title('Vanta Vision 2K27 • Launcher')
        root.geometry('720x650');root.minsize(700,630);root.configure(bg=BG)
        root.protocol('WM_DELETE_WINDOW',self.close)
        self.background=tk.Canvas(root,bg=BG,highlightthickness=0)
        self.background.pack(fill='both',expand=True);self.background.bind('<Configure>',self._draw_background)
        self.card=tk.Frame(self.background,bg=PANEL,highlightbackground=BORDER,highlightthickness=1)
        self._card_window=self.background.create_window(360,325,window=self.card,width=660,anchor='center')
        accents=tk.Frame(self.card,bg=PANEL,height=3);accents.pack(fill='x')
        tk.Frame(accents,bg=RED,height=3).pack(side='left',fill='x',expand=True)
        tk.Frame(accents,bg=BLUE,height=3).pack(side='left',fill='x',expand=True)
        top=tk.Frame(self.card,bg=PANEL);top.pack(fill='x',padx=24,pady=(22,16))
        try:
            raw=tk.PhotoImage(data=_VANTA_LOGO_B64,master=root)
            cropped=tk.PhotoImage(width=1209,height=1015,master=root)
            cropped.tk.call(str(cropped),'copy',str(raw),'-from',24,162,1233,1177,'-to',0,0)
            self.logo_image=cropped.subsample(11,11)
            tk.Label(top,image=self.logo_image,bg=PANEL).pack(side='left',padx=(0,18))
        except Exception:
            tk.Label(top,text='V',fg=BLUE,bg=PANEL,font=('Segoe UI',32,'bold')).pack(side='left',padx=(0,18))
        titles=tk.Frame(top,bg=PANEL);titles.pack(side='left',fill='x',expand=True)
        tk.Label(titles,text='VANTA VISION',fg=TEXT,bg=PANEL,font=('Segoe UI',25,'bold')).pack(anchor='w')
        tk.Label(titles,text='2K27',fg='#BC97FF',bg=PANEL,font=('Segoe UI',14,'bold')).pack(anchor='w')
        tk.Label(titles,text='LAUNCHER  /  RUNTIME & UPDATES',fg=MUTED,bg=PANEL,font=('Segoe UI',9)).pack(anchor='w',pady=(7,0))
        details=tk.Frame(self.card,bg=PANEL);details.pack(fill='x',padx=24,pady=(0,14))
        self.detail_labels={}
        for column,(key,heading,value) in enumerate((('version','LAUNCHER',LAUNCHER_BUILD),('python','PYTHON',f'{sys.version_info.major}.{sys.version_info.minor} / {struct.calcsize("P")*8}-bit'),('tls','CONNECTION','Verified TLS'))):
            details.grid_columnconfigure(column,weight=1,uniform='metrics')
            cell=tk.Frame(details,bg=PANEL_2,highlightbackground=BORDER,highlightthickness=1)
            cell.grid(row=0,column=column,sticky='nsew',padx=(0,7) if column<2 else 0)
            tk.Label(cell,text=heading,fg=MUTED,bg=PANEL_2,font=('Segoe UI',8,'bold')).pack(anchor='w',padx=12,pady=(9,3))
            label=tk.Label(cell,text=value,fg=TEXT,bg=PANEL_2,font=('Segoe UI',10,'bold'));label.pack(anchor='w',padx=12,pady=(0,9));self.detail_labels[key]=label
        status_box=tk.Frame(self.card,bg=PANEL_2,highlightbackground=BORDER,highlightthickness=1)
        status_box.pack(fill='x',padx=24)
        self.status=tk.Label(status_box,text='Checking your runtime…',bg=PANEL_2,fg=BLUE,font=('Segoe UI',11,'bold'),wraplength=560,anchor='w',justify='left')
        self.status.pack(fill='x',padx=14,pady=(12,7))
        self.runtime=tk.Label(status_box,text='Finding a compatible Python environment.',bg=PANEL_2,fg=MUTED,font=('Segoe UI',9),wraplength=560,anchor='w',justify='left')
        self.runtime.pack(fill='x',padx=14,pady=(0,11))
        from tkinter import ttk
        style=ttk.Style(root);style.theme_use('clam');style.configure('DRS.Horizontal.TProgressbar',background=BLUE,troughcolor='#100919',bordercolor='#100919',lightcolor=BLUE,darkcolor=BLUE)
        self.progress=ttk.Progressbar(self.card,style='DRS.Horizontal.TProgressbar',mode='indeterminate',maximum=100)
        self.progress.pack(fill='x',padx=24,pady=(12,0))
        self.progress_label=tk.Label(self.card,text='Ready',bg=PANEL,fg=CYAN,font=('Segoe UI',9),anchor='w')
        self.progress_label.pack(fill='x',padx=24,pady=(5,0))
        self.notes=tk.Label(self.card,text='Updates keep your protected core intact. Runtime repair uses the matching Python environment.',bg=PANEL,fg=MUTED,font=('Segoe UI',9),wraplength=590,justify='left',anchor='w')
        self.notes.pack(fill='x',padx=24,pady=(12,16))
        row=tk.Frame(self.card,bg=PANEL);row.pack(fill='x',padx=20,pady=(0,15))
        for col in range(4):row.grid_columnconfigure(col,weight=1,uniform='actions')
        self.check_btn=VButton(row,text='Check Updates',command=self.check_async)
        self.update_btn=VButton(row,text='Install Update',command=self.update_async,state='disabled')
        self.repair_btn=VButton(row,text='Repair Runtime',command=self.repair_async)
        self.launch_btn=VButton(row,text='Launch',command=self.do_launch,bg=BLUE,state='disabled')
        for col,button in enumerate((self.check_btn,self.update_btn,self.repair_btn,self.launch_btn)):button.grid(row=0,column=col,padx=4,sticky='ew')
        footer=tk.Frame(self.card,bg=PANEL);footer.pack(fill='x',padx=24,pady=(0,18))
        self.core_label=tk.Label(footer,text='Protected runtime check pending.',bg=PANEL,fg=MUTED,font=('Segoe UI',9),anchor='w');self.core_label.pack(side='left',fill='x',expand=True)
        for text,command in (('Logs',self.open_log),('Files',self.open_folder)):
            button=tk.Button(footer,text=text,command=command,bg=PANEL,fg='#C49EFF',relief='flat',bd=0,cursor='hand2',font=('Segoe UI',9,'underline'));button.pack(side='right',padx=(9,0))
        root.after(40,self._drain_events)
        root.after(100,self.scan_async)

    def _draw_background(self,event):
        c=self.background;c.delete('circuit');w=event.width;h=event.height
        for x in range(0,w,40):c.create_line(x,0,x,h,fill='#160D23',tags='circuit')
        for y in range(0,h,40):c.create_line(0,y,w,y,fill='#160D23',tags='circuit')
        c.create_line(0,75,65,75,110,120,110,230,fill='#54248D',width=2,tags='circuit')
        c.create_line(w,h-70,w-75,h-70,w-120,h-115,w-120,h-230,fill='#713ABA',width=2,tags='circuit')
        c.tag_lower('circuit');c.coords(self._card_window,w/2,h/2)

    def _post_ui(self, callback):
        if not self._closed:self._events.put(callback)

    def _drain_events(self):
        if self._closed:return
        for _ in range(50):
            try:callback=self._events.get_nowait()
            except queue.Empty:break
            try:callback()
            except Exception:log(traceback.format_exc())
        if not self._closed:self.root.after(40,self._drain_events)

    def set_status(self,msg,color=BLUE):
        self._post_ui(lambda:self.status.config(text=str(msg),fg=color))

    def set_notes(self,notes):
        text='  •  '.join(str(x) for x in notes[:4]) if isinstance(notes,list) else str(notes)
        self._post_ui(lambda:self.notes.config(text=text))

    def set_progress(self,value,label):
        def apply():
            self.progress.stop();self.progress.config(mode='determinate')
            self.progress['value']=max(0,min(100,value))
            self.progress_label.config(text=f'{value:.0f}%  •  {label}')
        self._post_ui(apply)

    def _begin(self):
        if self._closed or self._busy:return False
        self._busy=True;self.progress.config(mode='indeterminate');self.progress['value']=0;self.progress.start(12);self.progress_label.config(text='Working…',fg=CYAN)
        for button in (self.check_btn,self.update_btn,self.repair_btn,self.launch_btn):button.config(state='disabled')
        return True

    def _finish(self):
        if self._closed:return
        self._busy=False;self.progress.stop()
        if str(self.progress['mode'])=='indeterminate':self.progress['value']=0
        if self.progress_label.cget('text')=='Working…':self.progress_label.config(text='Ready')
        self.check_btn.config(state='normal');self.repair_btn.config(state='normal')
        self.update_btn.config(state='normal' if self.manifest and update_needed(self.manifest) else 'disabled')
        forced=_mandatory_update_required(self.manifest)
        # Keep Launch clickable: its preflight gives an actionable reason instead of a silent gray button.
        self.launch_btn.config(state='normal',text='Update Required' if forced else 'Launch')

    def refresh_runtime(self):
        ok,msg=verify_runtime(self.manifest)
        self.core_label.config(text=msg,fg=GOOD if ok else WARN)

    def _show_runtime(self,info):
        self._runtime_ready=True
        self.runtime.config(text=info['exe'],fg=GOOD)
        self.detail_labels['python'].config(text=f'{info["version"][0]}.{info["version"][1]} / 64-bit')
        self.detail_labels['tls'].config(text='TLS verified',fg=GOOD)

    def scan_async(self):
        if not self._begin():return
        threading.Thread(target=self._scan,daemon=True).start()

    def _scan(self):
        try:
            info=runtime_preflight();self._post_ui(lambda:self._show_runtime(info))
            self.set_status('Runtime ready.',GOOD)
        except Exception as exc:
            self.set_status('Runtime needs attention.',WARN);self.set_notes(str(exc))
        finally:
            self._post_ui(self.refresh_runtime);self._post_ui(self._finish)
            if AUTO_CHECK_ON_OPEN:self._post_ui(self.check_async)

    def check_async(self):
        if not self._begin():return
        self.set_status('Checking for updates…')
        threading.Thread(target=self._check,daemon=True).start()

    def _check(self):
        try:
            manifest=check_manifest();self.manifest=manifest
            latest=str(manifest.get('latest_version') or manifest.get('version') or 'unknown')
            self.set_notes(manifest.get('notes') or manifest.get('patch_notes') or f'Latest release: {latest}')
            self.set_status(f'Update available: {latest}' if update_needed(manifest) else 'Your files are up to date.',WARN if update_needed(manifest) else GOOD)
        except Exception as exc:
            log(str(exc));self.set_status('Update check could not finish.',BAD);self.set_notes(str(exc))
        finally:self._post_ui(self.refresh_runtime);self._post_ui(self._finish)

    def update_async(self):
        if not self.manifest:return self.check_async()
        if not self._begin():return
        threading.Thread(target=self._update,daemon=True).start()

    def _update(self):
        try:
            installed=install_update(self.manifest,self.set_status,self.set_progress)
            self.set_status('Update installed. Restart the host if prompted.',GOOD)
            self.set_notes(', '.join(installed) or 'No files to install.')
        except Exception as exc:
            log(traceback.format_exc());self.set_status('Update could not be installed.',BAD);self.set_notes(str(exc));self._post_ui(lambda:self.progress_label.config(text='Update stopped — see details below',fg=BAD))
        finally:self._post_ui(self.refresh_runtime);self._post_ui(self._finish)

    def repair_async(self):
        if not self._begin():return
        self._runtime_ready=False
        threading.Thread(target=self._repair,daemon=True).start()

    def _repair(self):
        try:
            info=repair_runtime(self.set_status);self._post_ui(lambda:self._show_runtime(info))
            self.set_status('Runtime dependencies are ready.',GOOD)
        except Exception as exc:
            log(traceback.format_exc());self.set_status('Runtime repair needs attention.',BAD);self.set_notes(str(exc))
        finally:self._post_ui(self.refresh_runtime);self._post_ui(self._finish)

    def do_launch(self):
        if not self._begin():return
        self.set_status('Verifying runtime and protected core…')
        threading.Thread(target=self._launch_check,daemon=True).start()

    def _launch_check(self):
        try:
            if _mandatory_update_required(self.manifest):
                raise RuntimeError('The update manifest requires an update before launch. Install the update and restart the host. If update hashes mismatch, the publisher must correct the manifest first.')
            runtime_preflight();ok,msg=verify_runtime(self.manifest)
            if not ok:raise RuntimeError(msg)
            self._post_ui(self._accept_launch)
        except Exception as exc:
            self.set_status('Launch stopped before loading the core.',BAD);self.set_notes(str(exc));self._post_ui(self._finish)

    def _accept_launch(self):
        self.launch=True;self.close()

    def close(self):
        self._closed=True;self.root.destroy()

    def open_folder(self):
        _open_path(_HERE)

    def open_log(self):
        if not os.path.isfile(LOG_PATH):log('Launcher log opened.')
        _open_path(LOG_PATH)


def _open_path(path):
    if os.name=='nt':os.startfile(path)
    else:subprocess.Popen(['open' if sys.platform=='darwin' else 'xdg-open',path])


def run_updater_ui_blocking():
    log('Updater starting.')
    if tk is None:
        raise RuntimeError('Tkinter is unavailable in the host Python. Install the matching full Python build with Tcl/Tk support.')
    try:root=tk.Tk()
    except Exception as exc:
        raise RuntimeError('The launcher window could not open. Check Tcl/Tk support in the host Python. '+str(exc)) from exc
    ui=UpdaterUI(root);root.mainloop()
    return bool(ui.launch)


class GCVWorker:
    def __new__(cls, *args, **kwargs):
        if not run_updater_ui_blocking():
            raise ImportError("Vanta Vision 2K27: launch cancelled.")
        core = load_runtime()
        real = getattr(core, "GCVWorker", None)
        if real is None:
            raise ImportError("Vanta Vision 2K27: protected runtime does not expose GCVWorker.")
        return real(*args, **kwargs)


# Compatible class aliases for host worker discovery.
CVWorker = GCVWorker
VWorker = GCVWorker

def main():
    if run_updater_ui_blocking():
        load_runtime()


if __name__ == "__main__":
    main()
